427	    /**
428	     * Immutable, structured {@code OWNER_CREATED} audit event. Serialized to a compact JSON object
429	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} for the {@code AUDIT}
430	     * log. Being a record, once constructed its fields cannot change, so the emitted event is a faithful
431	     * snapshot of the owner at creation time.
432	     *
433	     * @param seq strictly increasing sequence number across all creates
434	     * @param ownerId the created owner's id
435	     * @param memberId the owner's current primary identifier at creation time
436	     * @param membershipLevel the owner's effective membership level at creation time
437	     */
438	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel) {
439	
440	        private String toJson() {
441	            return "{\"seq\":" + seq
442	                + ",\"ownerId\":" + ownerId
443	                + ",\"memberId\":" + jsonValue(memberId)
444	                + ",\"membershipLevel\":" + membershipLevel
445	                + ",\"event\":\"OWNER_CREATED\"}";
446	        }
447	
448	        /** Renders a nullable string as a JSON string literal (with escaping) or {@code null}. */
449	        private static String jsonValue(String value) {
450	            if (value == null) {
451	                return "null";
452	            }
453	            StringBuilder sb = new StringBuilder(value.length() + 2);
454	            sb.append('"');
455	            for (int i = 0; i < value.length(); i++) {
456	                char c = value.charAt(i);
457	                switch (c) {
458	                    case '"' -> sb.append("\\\"");
459	                    case '\\' -> sb.append("\\\\");
460	                    case '\n' -> sb.append("\\n");
461	                    case '\r' -> sb.append("\\r");
462	                    case '\t' -> sb.append("\\t");
463	                    default -> sb.append(c);
464	                }
465	            }
466	            sb.append('"');
467	            return sb.toString();
468	        }
469	    }
