471	    /**
472	     * Builds the unified member id for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
473	     * where {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion}),
474	     * {@code FY} is the two-digit fiscal year of the owner's business-day-adjusted registration date,
475	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized
476	     * telephone concatenated with the last name (the same HASH8 used by the region-and-hash identity), and
477	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. For
478	     * example an owner in the NSW postcode range registered in fiscal year 2026 gets an id such as
479	     * {@code 'NSW263F2A1B9C7'}.
480	     *
481	     * <p>When the computed member id collides with an existing owner's member id, it is de-duplicated by
482	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique across
483	     * all existing owners' member ids. The de-duplicated id is what gets assigned.
484	     *
485	     * @param owner the owner being created, whose postcode, city, registration date and last name feed the id
486	     * @param normalizedTelephone the owner's E.164-normalized telephone
487	     * @return the assigned member id, de-duplicated against existing owners if necessary
488	     */
489	    private String buildMemberId(Owner owner, String normalizedTelephone) {
490	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
491	        String fiscalYear = String.format("%02d", ownerMapper.fiscalYearValue(owner.getRegistrationDate()) % 100);
492	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
493	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
494	        String base = region + fiscalYear + hash8;
495	        String memberId = base + luhnCheckDigit(base);
496	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
497	            .map(Owner::getMemberId)
498	            .filter(id -> id != null)
499	            .collect(java.util.stream.Collectors.toSet());
500	        if (!existingIds.contains(memberId)) {
501	            return memberId;
502	        }
503	        int n = 2;
504	        while (existingIds.contains(memberId + "-" + n)) {
505	            n++;
506	        }
507	        return memberId + "-" + n;
508	    }
509	
510	    /**
511	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in the given string.
512	     * Non-digit characters are ignored, so the check digit covers the region, fiscal-year and HASH8
513	     * digits of a member id's {@code '<REGION><FY><HASH8>'} base.
514	     *
515	     * @param value the string whose digits the check digit is computed over
516	     * @return the Luhn check digit, a single digit in {@code 0-9}
517	     */
518	    private int luhnCheckDigit(String value) {
519	        int sum = 0;
520	        boolean dbl = true;
521	        for (int i = value.length() - 1; i >= 0; i--) {
522	            char c = value.charAt(i);
523	            if (c < '0' || c > '9') {
524	                continue;
525	            }
526	            int d = c - '0';
527	            if (dbl) {
528	                d *= 2;
529	                if (d > 9) {
530	                    d -= 9;
531	                }
532	            }
533	            sum += d;
534	            dbl = !dbl;
535	        }
536	        return (10 - (sum % 10)) % 10;
537	    }
538	
539	    /**
540	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
541	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
542	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
543	     *
544	     * @param postcode the owner's postcode, may be {@code null}
545	     * @param city the owner's city, used to resolve the region when the postcode does not
546	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
547	     */
548	    private String deriveRegion(String postcode, String city) {
549	        if (postcode != null) {
550	            try {
551	                int value = Integer.parseInt(postcode.trim());
552	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
553	                    int[] range = entry.getValue();
554	                    if (value >= range[0] && value <= range[1]) {
555	                        return entry.getKey();
556	                    }
557	                }
558	            } catch (NumberFormatException ex) {
559	                // Not a numeric postcode; fall back to the city table below.
560	            }
561	        }
562	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
563	    }
564	
565	    /**
566	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
567	     * given input's UTF-8 bytes.
568	     *
569	     * @param input the string to hash
570	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
571	     */
572	    private String sha256Hex8(String input) {
573	        try {
574	            byte[] digest = MessageDigest.getInstance("SHA-256")
575	                .digest(input.getBytes(StandardCharsets.UTF_8));
576	            StringBuilder hex = new StringBuilder();
577	            for (int i = 0; i < 4; i++) {
578	                hex.append(String.format("%02X", digest[i]));
579	            }
580	            return hex.toString();
581	        } catch (NoSuchAlgorithmException ex) {
582	            throw new IllegalStateException("SHA-256 not available", ex);
583	        }
584	    }
