586	    /**
587	     * Rejects an owner payload that is missing or blank in any of the required fields
588	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
589	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
590	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
591	     * guard enforces the rule uniformly for every required field.
592	     *
593	     * @param ownerFieldsDto the submitted owner payload
594	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
595	     */
596	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
597	        List<String> invalidFields = new ArrayList<>();
598	        if (isBlank(ownerFieldsDto.getFirstName())) {
599	            invalidFields.add("firstName");
600	        }
601	        if (isBlank(ownerFieldsDto.getLastName())) {
602	            invalidFields.add("lastName");
603	        }
604	        if (isBlank(ownerFieldsDto.getAddressLine1())
605	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
606	            invalidFields.add("address");
607	        }
608	        if (isBlank(ownerFieldsDto.getCity())) {
609	            invalidFields.add("city");
610	        }
611	        if (isBlank(ownerFieldsDto.getTelephone())) {
612	            invalidFields.add("telephone");
613	        }
614	        if (!invalidFields.isEmpty()) {
615	            throw new InvalidOwnerFieldsException(invalidFields);
616	        }
617	    }
