623	    /**
624	     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
625	     * excluded from the create endpoint's duplicate and identity checks, so it never blocks the
626	     * creation of a new owner. A {@code null} flag (an owner predating the soft-delete column) is
627	     * treated as not deleted.
628	     *
629	     * @param owner an existing owner
630	     * @return {@code true} if the owner is flagged deleted
631	     */
632	    private boolean isDeleted(Owner owner) {
633	        return Boolean.TRUE.equals(owner.getDeleted());
634	    }
