636	    /**
637	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
638	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
639	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
640	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
641	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
642	     * and returned exactly as given.
643	     *
644	     * @param postcode the submitted postcode, may be {@code null} when absent
645	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
646	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
647	     */
648	    private void validatePostcode(String postcode, String city) {
649	        if (postcode == null) {
650	            return;
651	        }
652	        if (!postcode.matches("[0-9]{4}")) {
653	            throw new InvalidOwnerFieldsException(List.of("postcode"));
654	        }
655	        String region = city == null ? null : CITY_REGION.get(city);
656	        if (region == null) {
657	            return;
658	        }
659	        int[] range = REGION_POSTCODES.get(region);
660	        int value = Integer.parseInt(postcode);
661	        if (value < range[0] || value > range[1]) {
662	            throw new InvalidOwnerFieldsException(List.of("postcode"));
663	        }
664	    }
