666	    /**
667	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
668	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
669	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
670	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
671	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
672	     *
673	     * @param telephone the raw telephone value from the submitted owner payload
674	     * @return the normalized E.164 telephone number
675	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
676	     */
677	    private String normalizeTelephone(String telephone) {
678	        String raw = telephone == null ? "" : telephone.strip();
679	        boolean hasCountryCode = raw.startsWith("+");
680	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
681	        String digits;
682	        if (hasCountryCode) {
683	            digits = cleaned.substring(1);
684	        } else {
685	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
686	            digits = "61" + national;
687	        }
688	        if (!digits.matches("[0-9]{8,15}")) {
689	            throw new InvalidOwnerFieldsException(List.of("telephone"));
690	        }
691	        validateNationalNumberLength(digits);
692	        return "+" + digits;
693	    }
694	
695	    /**
696	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
697	     * country calling code) has the exact length required for that country. The country code is matched
698	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
699	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
700	     *
701	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
702	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
703	     */
704	    private void validateNationalNumberLength(String digits) {
705	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
706	            String countryCode = entry.getKey();
707	            if (digits.startsWith(countryCode)) {
708	                int nationalLength = digits.length() - countryCode.length();
709	                if (nationalLength != entry.getValue()) {
710	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
711	                }
712	                return;
713	            }
714	        }
715	    }
716	
717	    /**
718	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
719	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
720	     * accepted value is trimmed and lower-cased before it is stored and returned.
721	     *
722	     * @param email the raw email value from the submitted owner payload, may be {@code null}
723	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
724	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
725	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
726	     */
727	    private String normalizeEmail(String email) {
728	        if (email == null) {
729	            return null;
730	        }
731	        String trimmed = email.strip();
732	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
733	            throw new InvalidOwnerFieldsException(List.of("email"));
734	        }
735	        String normalized = trimmed.toLowerCase(Locale.ROOT);
736	        String domain = normalized.substring(normalized.indexOf('@') + 1);
737	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
738	            throw new InvalidOwnerFieldsException(List.of("email"));
739	        }
740	        return normalized;
741	    }
