743	    /**
744	     * Rejects creating an owner whose derived identity key (the SHA-256 hex digest of
745	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}, see {@link OwnerMapper#identityKey})
746	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only when
747	     * their whole identity keys match, so owners who share a last-name Soundex but differ in telephone or
748	     * email are not duplicates and are admitted (flagged as a soft match instead). Such an owner is rejected
749	     * with a 409, <em>unless</em> the request opts into {@code sharesHousehold}, which bypasses the block
750	     * entirely.
751	     *
752	     * @param owner the owner being created, whose identity key is matched
753	     * @param sharesHousehold whether the request declared the owner a shared-household member
754	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
755	     */
756	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
757	        if (sharesHousehold) {
758	            return;
759	        }
760	        String identityKey = ownerMapper.identityKey(owner);
761	        boolean duplicate = this.clinicService.findAllOwners().stream()
762	            .filter(existing -> !isDeleted(existing))
763	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
764	        if (duplicate) {
765	            throw new DuplicateOwnerIdentityException(identityKey);
766	        }
767	    }
