769	    /**
770	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
771	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
772	     * owner whose {@link OwnerMapper#identityKey identity key} <em>differs</em> from an existing owner's
773	     * but which shares that owner's last-name {@link OwnerMapper#soundex Soundex code} and postcode. When
774	     * such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
775	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
776	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
777	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
778	     *
779	     * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
780	     * but different telephones no longer collide on the identity key, so they are admitted as a soft match
781	     * here rather than rejected as a hard household duplicate.
782	     *
783	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the duplicate
784	     * block) is never a <em>suspected</em> duplicate: it is knowingly created as another member of the
785	     * household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
786	     * {@code null} without consulting the existing population.
787	     *
788	     * @param owner the owner being created, whose last-name Soundex and postcode are matched
789	     * @param sharesHousehold whether the request declared the owner a shared-household member
790	     */
791	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
792	        if (sharesHousehold) {
793	            owner.setPossibleDuplicateOf(null);
794	            owner.setPossibleDuplicate(false);
795	            return;
796	        }
797	        String postcode = owner.getPostcode();
798	        Integer matchId = null;
799	        if (postcode != null) {
800	            String identityKey = ownerMapper.identityKey(owner);
801	            String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
802	            for (Owner existing : this.clinicService.findAllOwners()) {
803	                if (!isDeleted(existing)
804	                    && postcode.equals(existing.getPostcode())
805	                    && lastNameCode.equals(OwnerIdentity.soundex(existing.getLastName()))
806	                    && !identityKey.equals(ownerMapper.identityKey(existing))
807	                    && existing.getId() != null
808	                    && (matchId == null || existing.getId() < matchId)) {
809	                    matchId = existing.getId();
810	                }
811	            }
812	        }
813	        owner.setPossibleDuplicateOf(matchId);
814	        owner.setPossibleDuplicate(matchId != null);
815	    }
816	
817	    /**
818	     * The maximum number of owners a single city may contain. Once a city already holds this many
819	     * owners, creating another owner in that city is rejected.
820	     */
821	    private static final int MAX_OWNERS_PER_CITY = 50;
822	
823	    /**
824	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
825	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
826	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
827	     * counting used elsewhere.
828	     *
829	     * @param city the city of the owner being created
830	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
831	     */
832	    /**
833	     * The maximum number of owners that may be registered on a single day. Once this many owners
834	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
835	     */
836	    private static final int MAX_OWNERS_PER_DAY = 100;
837	
838	    /**
839	     * Fixed list of public holidays. A registration date that lands on one of these dates is not a
840	     * business day and is rolled forward to the next non-holiday weekday.
841	     */
842	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
843	        LocalDate.of(2026, 1, 1),
844	        LocalDate.of(2026, 1, 26),
845	        LocalDate.of(2026, 4, 25),
846	        LocalDate.of(2026, 12, 25),
847	        LocalDate.of(2026, 12, 28));
848	
849	    /**
850	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
851	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
852	     * registration date of the owner being created.
853	     *
854	     * @param registrationDate the registration date of the owner being created
855	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
856	     */
857	    /**
858	     * Rolls an effective registration date forward onto a business day. A registration date must fall
859	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
860	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
861	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
862	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
863	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
864	     * uses this adjusted date.
865	     *
866	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
867	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
868	     */
869	    /**
870	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
871	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
872	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
873	     * against the date exactly as supplied, before it is rolled forward onto a business day.
874	     *
875	     * @param registrationDate the registration date supplied in the request, may be {@code null}
876	     * @throws FutureRegistrationDateException if the supplied date is after the server date
877	     */
878	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
879	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
880	            throw new FutureRegistrationDateException(registrationDate);
881	        }
882	    }
883	
884	    private LocalDate rollToBusinessDay(LocalDate date) {
885	        LocalDate adjusted = date;
886	        while (!isBusinessDay(adjusted)) {
887	            adjusted = adjusted.plusDays(1);
888	        }
889	        return adjusted;
890	    }
891	
892	    private boolean isBusinessDay(LocalDate date) {
893	        DayOfWeek day = date.getDayOfWeek();
894	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
895	            return false;
896	        }
897	        return !PUBLIC_HOLIDAYS.contains(date);
898	    }
899	
900	    private void rejectDailyLimitReached(LocalDate registrationDate) {
901	        long ownersToday = this.clinicService.findAllOwners().stream()
902	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
903	            .count();
904	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
905	            throw new DailyOwnerLimitExceededException(registrationDate);
906	        }
907	    }
908	
909	    /**
910	     * The number of owners that must already share a {@code registrationDate} before a newly created
911	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
912	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
913	     */
914	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
915	
916	    /**
917	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
918	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
919	     * the same registration date at the time this owner is created. Existing owners are counted by their
920	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
921	     * daily create-limit accumulation.
922	     *
923	     * @param registrationDate the registration date of the owner being created
924	     * @return {@code true} if the day already holds more than the threshold number of owners
925	     */
926	    private boolean isBulkSignupDay(LocalDate registrationDate) {
927	        long ownersToday = this.clinicService.findAllOwners().stream()
928	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
929	            .count();
930	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
931	    }
932	
933	    private void rejectCityAtCapacity(String city) {
934	        String normalizedCity = normalizeForComparison(city);
935	        long ownersInCity = this.clinicService.findAllOwners().stream()
936	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
937	            .count();
938	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
939	            throw new OwnerCityCapacityExceededException(city);
940	        }
941	    }
942	
943	    /**
944	     * The number of owners a city must already hold before a newly created owner in that city is
945	     * flagged as approaching capacity. Once a city already contains at least this many owners (but
946	     * still fewer than {@link #MAX_OWNERS_PER_CITY}), the new owner's {@code capacityWarning} is set.
947	     */
948	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
949	
950	    /**
951	     * Determines whether the owner being created is approaching the per-city capacity limit. The
952	     * warning is raised when the owner's city already contains between {@link
953	     * #CITY_CAPACITY_WARNING_THRESHOLD} and {@code MAX_OWNERS_PER_CITY - 1} owners (inclusive) at the
954	     * time this owner is created; the hard rejection at {@link #MAX_OWNERS_PER_CITY} is unchanged.
955	     * Existing owners' cities are compared case-insensitively with surrounding and repeated internal
956	     * whitespace collapsed (see {@link #normalizeForComparison}), matching {@link #rejectCityAtCapacity}.
957	     *
958	     * @param city the city of the owner being created
959	     * @return {@code true} if the city already holds 40-49 owners
960	     */
961	    private boolean isApproachingCityCapacity(String city) {
962	        String normalizedCity = normalizeForComparison(city);
963	        long ownersInCity = this.clinicService.findAllOwners().stream()
964	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
965	            .count();
966	        return ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY;
967	    }
968	
969	    /**
970	     * Counts how many owners belong to the household the owner being created has just been assigned to,
971	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
972	     * given identifier; the owner being created is added on because it is counted before being persisted.
973	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
974	     * household of one. The value is snapshotted on the owner.
975	     *
976	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
977	     * @return the number of household members, including the owner being created
978	     */
979	    private int countHousehold(String householdId) {
980	        if (householdId == null) {
981	            return 1;
982	        }
983	        long existing = this.clinicService.findAllOwners().stream()
984	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
985	            .count();
986	        return (int) existing + 1;
987	    }
988	
989	    /**
990	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
991	     * A new owner's membership level cannot exceed one above the current maximum membership level among
992	     * their existing household members: the returned cap is that maximum plus one. Existing household
993	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
994	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
995	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
996	     *
997	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
998	     * @return one above the highest household member's membership level, or {@code null} when none exist
999	     */
1000	    private Integer membershipLevelCap(String householdId) {
1001	        if (householdId == null) {
1002	            return null;
1003	        }
1004	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
1005	            .filter(existing -> !isDeleted(existing))
1006	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1007	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
1008	            .max();
1009	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
1010	    }
1011	
1012	    /**
1013	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
1014	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
1015	     * name is normalized for case- and whitespace-insensitive comparison (see
1016	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
1017	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
1018	     * regardless of creation order, making them members of one household.
1019	     *
1020	     * @param lastName the owner's last name
1021	     * @param postcode the owner's postcode, may be {@code null}
1022	     * @return the deterministic household identifier
1023	     */
1024	    private String householdId(String lastName, String postcode) {
1025	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
1026	        try {
1027	            byte[] digest = MessageDigest.getInstance("SHA-256")
1028	                .digest(key.getBytes(StandardCharsets.UTF_8));
1029	            StringBuilder hex = new StringBuilder();
1030	            for (int i = 0; i < 6; i++) {
1031	                hex.append(String.format("%02x", digest[i]));
1032	            }
1033	            return hex.toString();
1034	        } catch (NoSuchAlgorithmException ex) {
1035	            throw new IllegalStateException("SHA-256 not available", ex);
1036	        }
1037	    }
1038	
1039	    /**
1040	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
1041	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
1042	     * result is lower-cased. A {@code null} value normalizes to the empty string.
1043	     *
1044	     * @param value the value to normalize, may be {@code null}
1045	     * @return the normalized value
1046	     */
1047	    private String normalizeForComparison(String value) {
1048	        if (value == null) {
1049	            return "";
1050	        }
1051	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1052	    }
1053	
1054	    /**
1055	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
1056	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
1057	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
1058	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
1059	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
1060	     * that is stored, returned, and used for every address comparison (household duplicate detection
1061	     * and the shared household id).
1062	     *
1063	     * @param address the raw address value from the submitted owner payload, may be {@code null}
1064	     * @return the normalized address
1065	     */
1066	    /**
1067	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
1068	     * the structured fields over the flat {@code address} input for backward compatibility. When a
1069	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
1070	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
1071	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
1072	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
1073	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
1074	     *
1075	     * @param owner the owner being created, whose raw address fields are normalized in place
1076	     */
1077	    private void applyAddress(Owner owner) {
1078	        String line1 = owner.getAddressLine1();
1079	        if (line1 != null && !line1.isBlank()) {
1080	            String normalizedLine1 = normalizeAddress(line1);
1081	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
1082	            owner.setAddressLine1(normalizedLine1);
1083	            if (!normalizedLine2.isEmpty()) {
1084	                owner.setAddressLine2(normalizedLine2);
1085	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
1086	            } else {
1087	                owner.setAddressLine2(null);
1088	                owner.setAddress(normalizedLine1);
1089	            }
1090	        } else {
1091	            owner.setAddressLine1(null);
1092	            owner.setAddressLine2(null);
1093	            owner.setAddress(normalizeAddress(owner.getAddress()));
1094	        }
1095	    }
1096	
1097	    private String normalizeAddress(String address) {
1098	        if (address == null) {
1099	            return "";
1100	        }
1101	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1102	        if (collapsed.isEmpty()) {
1103	            return "";
1104	        }
1105	        String[] tokens = collapsed.split(" ");
1106	        StringBuilder normalized = new StringBuilder();
1107	        for (int i = 0; i < tokens.length; i++) {
1108	            if (i > 0) {
1109	                normalized.append(' ');
1110	            }
1111	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1112	        }
1113	        return normalized.toString();
1114	    }
1115	}
